DEFAULT_OUTPUT = '/root/shared-nvme/BRIGHT-checkpoints/SRAC_JOINT_LIVE_RECOVERY_V2'


def option_value(arguments, name, default):
    for index, value in enumerate(arguments):
        if value == name and index + 1 < len(arguments):
            return arguments[index + 1]
        if value.startswith(name + '='):
            return value.split('=', 1)[1]
    return default


def extract(parent):
    data = base64.b85decode(PAYLOAD)
    if hashlib.sha256(data).hexdigest() != PAYLOAD_SHA256:
        raise ValueError('Embedded release checksum mismatch')
    with zipfile.ZipFile(io.BytesIO(data)) as archive:
        entries = archive.infolist()
        names = set()
        for member in entries:
            parts = PurePosixPath(member.filename).parts
            if (len(parts) != 2 or parts[0] != 'joint_live_recovery_v2'
                    or parts[1] in ('.', '..') or member.is_dir()
                    or member.filename in names):
                raise ValueError('Invalid embedded release member: ' + member.filename)
            names.add(member.filename)
        manifest_name = 'joint_live_recovery_v2/SHA256SUMS.json'
        manifest = json.loads(archive.read(manifest_name))
        expected = manifest['files'] if 'files' in manifest else manifest
        declared = {f'joint_live_recovery_v2/{name}' for name in expected}
        if names != declared | {manifest_name}:
            raise ValueError('Embedded manifest does not describe the exact release')
        for name, sha256 in expected.items():
            if hashlib.sha256(archive.read('joint_live_recovery_v2/' + name)).hexdigest() != sha256:
                raise ValueError('Embedded file checksum mismatch: ' + name)
        folder = Path(tempfile.mkdtemp(prefix='joint_live_', dir=str(parent)))
        archive.extractall(folder)
    return folder / 'joint_live_recovery_v2'


def main(argv=None):
    wrapper = argparse.ArgumentParser(add_help=False)
    wrapper.add_argument('--foreground', action='store_true')
    wrapper.add_argument('--extract-only', action='store_true')
    args, remaining = wrapper.parse_known_args(argv)
    tool = extract(Path(__file__).resolve().parent)
    print('TOOL_DIR=' + str(tool), flush=True)
    if args.extract_only:
        print('EXTRACT_ONLY: verified helpers extracted; no probe or training started.', flush=True)
        return 0
    env = dict(os.environ)
    env['PYTHONDONTWRITEBYTECODE'] = '1'
    command = [sys.executable, '-u', str(tool / 'recovery.py'), *remaining]
    stage = option_value(remaining, '--stage', 'recover')
    if args.foreground or stage not in ('recover', 'probe') or any(x in ('-h', '--help') for x in remaining):
        print('Launcher options: --foreground, --extract-only; recovery options follow.', flush=True)
        os.execve(sys.executable, command, env)
    output = Path(option_value(remaining, '--output-parent', DEFAULT_OUTPUT)).expanduser().resolve()
    output.mkdir(parents=True, exist_ok=True)
    stamp = datetime.now(timezone.utc).strftime('%Y%m%d_%H%M%S_%f') + '_' + str(os.getpid())
    log = output / ('launcher_' + stamp + '.log')
    record = output / ('launcher_' + stamp + '.json')
    with log.open('xb') as stream:
        child = subprocess.Popen(command, stdin=subprocess.DEVNULL, stdout=stream,
                                 stderr=subprocess.STDOUT, env=env, start_new_session=True,
                                 close_fds=True)
    with record.open('x', encoding='utf-8') as stream:
        json.dump({'pid': child.pid, 'tool': str(tool), 'log': str(log), 'command': command,
                   'started_is_not_passed': True}, stream, ensure_ascii=False, indent=2)
    print('恢复启动器PID=' + str(child.pid), flush=True)
    print('启动日志=' + str(log), flush=True)
    print('查看：tail -n 60 -f "' + str(log) + '"', flush=True)
    print('只启动一次。启动不等于通过；现场检查、CPU后端检查、1500步Val450和完整性检查通过后才更新1501步。', flush=True)
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
